function formatCategory(cat: string): string {
  const special: Record<string, string> = { 'ai': 'AI', 'ufo': 'UFO', 'snake-eyes': 'Snake Eyes' }
  if (special[cat]) return special[cat]
  return cat.split('/').map(part => part.split('-').map(w => special[w] || w.charAt(0).toUpperCase() + w.slice(1)).join(' ')).join('/')
}
function tierColor(cat: string): string { if (cat === 'legendary') return '#d4af37'; if (cat === 'epic') return '#a78bfa'; return '#f87171' }
function tierEmoji(cat: string): string { if (cat === 'legendary') return '\u2b50'; if (cat === 'epic') return '\ud83d\udd25'; if (cat === 'snake-eyes') return '\ud83c\udfb2'; return '' }

