async function apiAddUrl(body: any): Promise<{ ok: boolean; added?: number; updated?: number; skipped?: number; error?: string }> { try { const r = await fetch('/api/admin/add-url', { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify(body) }); return await r.json() } catch (e: any) { return { ok: false, error: e?.message || 'Request failed' } } }
async function apiUpdateUrl(body: any): Promise<{ ok: boolean; error?: string; count?: number }> { try { const r = await fetch('/api/admin/update-url', { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify(body) }); return await r.json() } catch (e: any) { return { ok: false, error: e?.message || 'Request failed' } } }
async function apiModerate(body: any): Promise<{ ok: boolean; error?: string; count?: number }> { try { const r = await fetch('/api/admin/moderate', { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify(body) }); return await r.json() } catch (e: any) { return { ok: false, error: e?.message || 'Request failed' } } }
async function apiDeleteUrl(urlId: number): Promise<{ ok: boolean; error?: string }> { try { const r = await fetch('/api/admin/delete-url', { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ urlId }) }); return await r.json() } catch (e: any) { return { ok: false, error: e?.message || 'Request failed' } } }

