  async function loadUrls(searchTerm?: string) { setLoading(true); let query = supabase.from('urls').select('id, url, domain, title, description, category, is_dead, created_at, embed_status'); if (searchTerm && searchTerm.trim()) { query = query.or(`domain.ilike.%${searchTerm.trim()}%,url.ilike.%${searchTerm.trim()}%,title.ilike.%${searchTerm.trim()}%,category.ilike.%${searchTerm.trim()}%`) } query = query.order('domain', { ascending: true }).limit(500); const { data } = await query; setUrls(data || []); setLoading(false) }
  async function loadStats() { const { count: total } = await supabase.from('urls').select('*', { count: 'exact', head: true }); const { count: dead } = await supabase.from('urls').select('*', { count: 'exact', head: true }).eq('is_dead', true); const { data: cats } = await supabase.from('urls').select('category').not('category', 'is', null); const unique = Array.from(new Set((cats || []).map((c: any) => c.category).filter(Boolean))); setStats({ total: total || 0, dead: dead || 0, categories: unique as string[] }) }
