  async function tierMoveDown(tier: string, urlId: number) { playClick(); const list = tierUrls[tier]; const idx = list.findIndex(u => u.id === urlId); if (idx < 0 || idx >= list.length - 1) return; await supabase.from('urls').update({ tier_order: idx + 1 }).eq('id', list[idx].id); await supabase.from('urls').update({ tier_order: idx }).eq('id', list[idx + 1].id); loadTierUrls() }
