  async function loadInsights() { setInsightsLoading(true); try { const { data: events } = await supabase.from('url_events').select('url_id, event_type, session_id').in('event_type', ['mindblown', 'yawn', 'neutral']); if (!events || events.length === 0) { setInsightsData([]); setInsightsStats({ totalReactions: 0, totalMindblown: 0, totalYawn: 0, totalNeutral: 0, uniqueUrls: 0, uniqueUsers: 0 }); setInsightsLoading(false); return }; const urlMap: Record<number, { mindblown: number; yawn: number; neutral: number }> = {}; const userSet = new Set<string>(); let tMind = 0, tYawn = 0, tNeut = 0; for (const e of events) { if (!urlMap[e.url_id]) urlMap[e.url_id] = { mindblown: 0, yawn: 0, neutral: 0 }; if (e.event_type === 'mindblown') { urlMap[e.url_id].mindblown++; tMind++ } else if (e.event_type === 'yawn') { urlMap[e.url_id].yawn++; tYawn++ } else if (e.event_type === 'neutral') { urlMap[e.url_id].neutral++; tNeut++ }; userSet.add(e.session_id) }; setInsightsStats({ totalReactions: events.length, totalMindblown: tMind, totalYawn: tYawn, totalNeutral: tNeut, uniqueUrls: Object.keys(urlMap).length, uniqueUsers: userSet.size }); const urlIds = Object.keys(urlMap).map(Number); let allUrls: any[] = []; for (let i = 0; i < urlIds.length; i += 50) { const { data: ud } = await supabase.from('urls').select('id, url, domain, title, category').in('id', urlIds.slice(i, i + 50)); allUrls = allUrls.concat(ud || []) }; const urlLookup = new Map(allUrls.map(u => [u.id, u])); const scored: InsightUrl[] = []; for (const [idStr, counts] of Object.entries(urlMap)) { const id = Number(idStr); const u = urlLookup.get(id); if (!u) continue; const total = counts.mindblown + counts.yawn + counts.neutral; const score = total > 0 ? Math.round(((counts.mindblown - counts.yawn) / total) * 100) : 0; scored.push({ url_id: id, domain: u.domain || '', title: u.title || '', url: u.url, category: u.category || '', mindblown: counts.mindblown, yawn: counts.yawn, neutral: counts.neutral, total, score }) }; setInsightsData(scored) } catch (e) { console.error('Insights error:', e) }; setInsightsLoading(false) }
