  async function approveSubmission(subId: string, approvedTier: string) { playClick(); setSubApproving(subId); try { var sub = submissions.find(function (s: any) { return s.id === subId }); if (!sub) return; var goldAmount = GOLD_REWARDS[approvedTier] || 2; await supabase.from('url_submissions').update({ status: 'approved', approved_tier: approvedTier, gold_awarded: goldAmount, reviewed_at: new Date().toISOString() }).eq('id', subId); var normalizedUrl = sub.url.replace(/\/+$/, ''); await apiAddUrl({ mode: 'single', url: normalizedUrl, title: null, category: approvedTier === 'regular' ? null : approvedTier }); var { data: userStats } = await supabase.from('user_stats').select('gold_coins, total_points').eq('session_id', sub.session_id).single(); if (userStats) { await supabase.from('user_stats').update({ gold_coins: (userStats.gold_coins || 0) + goldAmount, total_points: (userStats.total_points || 0) + 5 }).eq('session_id', sub.session_id) } await supabase.from('notifications').insert({ session_id: sub.session_id, type: 'submission_approved', title: 'URL Approved!', body: 'Your submission was approved as ' + (approvedTier === 'regular' ? 'Regular' : formatCategory(approvedTier)) + '! +' + goldAmount + ' Gold', icon: '/emoji/Coin.png', color: '#d4af37', metadata: { gold: goldAmount, tier: approvedTier, url: sub.url } }); setMsg('\u2705 Approved! +' + goldAmount + ' Gold to user'); loadSubmissions(); loadStats() } catch (e: any) { setMsg('\u274c ' + (e.message || 'Failed')) } setSubApproving(null); setTimeout(() => setMsg(''), 3000) }
