  async function libraryBulkImport() { const lines = libBulkInput.trim().split('\n').filter(l => l.trim()); if (!lines.length) return; playClick(); setMsg('\u23f3 Importing to Library...'); const cat = libBulkCat || null; const res = await apiAddUrl({ mode: 'bulk', urls: lines, category: cat }); if (!res.ok) { playError(); setMsg('\u274c ' + res.error) } else { playSuccess(); setMsg('\u2705 ' + res.added + ' added! \u2014 Starting scans...'); runScanAll() }; setLibBulkInput(''); setLibBulkCat(''); loadLibrary(libraryCat); loadStats(); setTimeout(() => setMsg(''), 5000) }
  async function runScanAll() { setScanAllRunning(true); scanAllAbortRef.current = false; setScanAllLog([]); setScanAllPhase('Starting scans...'); var nextPhase = 'auto'; while (!scanAllAbortRef.current) { try { const r = await fetch('/api/admin/scan-all', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ phase: nextPhase }), credentials: 'include' }); const d = await r.json(); if (d.error) { playError(); setScanAllLog(p => [...p.slice(-80), '\u274c ' + d.error]); break }; if (d.done) { playSuccess(); setScanAllLog(p => [...p, '\u2705 ' + (d.message || 'All scans complete!')]); setScanAllPhase('Complete!'); break }; setScanAllPhase(d.phaseLabel || d.phase); nextPhase = d.phase; var detail = d.phase === 'dead' ? (d.alive || 0) + ' alive, ' + (d.dead || 0) + ' dead' : d.phase === 'categorize' ? (d.categorized || 0) + ' categorized, ' + (d.skipped || 0) + ' unknown' : d.phase === 'embed' ? (d.embeddable || 0) + ' embed, ' + (d.blocked || 0) + ' blocked' : ''; if (detail) { setScanAllLog(p => [...p.slice(-80), d.phaseLabel + ': ' + detail + ' \u2014 ' + (d.remaining || 0) + ' left']) } else { setScanAllLog(p => [...p.slice(-80), d.phaseLabel]) }; if ((d.remaining === 0 || d.remaining === undefined) && !d.done) { nextPhase = 'auto' } } catch (e: any) { setScanAllLog(p => [...p, 'Network error']); break } }; setScanAllRunning(false); loadStats(); loadEmbedStats(); loadDeadCheckStats() }
  function stopScanAll() { scanAllAbortRef.current = true }

